@dataclass
class OBSProcess:
    pid: int
    launcher: subprocess.Popen

    def poll(self) -> Optional[int]:
        return self.launcher.poll()


CURRENT_PROCESS: Optional[OBSProcess] = None
CURRENT_LOG_PATH: Optional[Path] = None


def run_osa(source: str, *arguments: str) -> str:
    result = subprocess.run(
        ["/usr/bin/osascript", "-", *arguments],
        input=source,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if result.returncode:
        raise RuntimeError(result.stderr.strip() or "osascript failed")
    return result.stdout.strip()


def process_script(body: str) -> str:
    return f"""
on run arguments
  set targetPid to (item 1 of arguments) as integer
  tell application "System Events"
    set targetProcess to first application process whose unix id is targetPid
    {body}
  end tell
end run
"""


def window_exists(pid: int, title: str) -> bool:
    return run_osa(
        process_script("return exists window (item 2 of arguments) of targetProcess"),
        str(pid), title,
    ) == "true"


def wait_for(description: str, predicate: Callable[[], bool], timeout: float = 30.0) -> None:
    deadline = time.monotonic() + timeout
    last_error: Optional[Exception] = None
    while time.monotonic() < deadline:
        try:
            if predicate():
                return
        except RuntimeError as error:
            last_error = error
        time.sleep(POLL_INTERVAL_SECONDS)
    detail = f": {last_error}" if last_error else ""
    raise AssertionError(f"Timed out waiting for {description}{detail}")


def window_text(pid: int, title: str) -> str:
    return run_osa(
        process_script("""
set targetWindow to window (item 2 of arguments) of targetProcess
set output to ""
repeat with textElement in every static text of targetWindow
  try
    set output to output & (name of textElement as text) & linefeed
  end try
end repeat
repeat with textElement in every text area of targetWindow
  try
    set output to output & (value of textElement as text) & linefeed
  end try
end repeat
return output
"""), str(pid), title,
    )


