class ScenarioTestResult(unittest.TextTestResult):
    def startTest(self, test: unittest.TestCase) -> None:
        print(f"TEST CASE START: {test.shortDescription() or test}", flush=True)
        super().startTest(test)

    def addSuccess(self, test: unittest.TestCase) -> None:
        print(f"TEST CASE RESULT: {test.shortDescription() or test}: PASSED", flush=True)
        super().addSuccess(test)

    def addFailure(self, test: unittest.TestCase, err) -> None:
        print(f"TEST CASE RESULT: {test.shortDescription() or test}: FAILED", flush=True)
        super().addFailure(test, err)

    def addError(self, test: unittest.TestCase, err) -> None:
        print(f"TEST CASE RESULT: {test.shortDescription() or test}: FAILED", flush=True)
        super().addError(test, err)


def prepare_workspace() -> None:
    ARTIFACTS.mkdir(parents=True, exist_ok=True)
    PROFILE_DIR.mkdir(parents=True)
    (CONFIG_ROOT / "basic/scenes").mkdir(parents=True)
    PLUGIN_CONFIG.mkdir(parents=True)
    PLUGIN_MANAGER_DIR.mkdir(parents=True)
    (PLUGIN_MANAGER_DIR / "modules.json").write_text(
        """[
  {
    "display_name": "mac-avcapture-legacy",
    "module_name": "mac-avcapture-legacy",
    "id": "",
    "version": "",
    "enabled": false,
    "sources": [],
    "outputs": [],
    "encoders": [],
    "services": []
  }
]
""",
        encoding="utf-8",
    )
    write_update_config("[update]", "version=0.0.0", "check_for_updates=true")
    for relative in ("Library/Caches", "Library/Logs/DiagnosticReports", "Library/Preferences"):
        (WORKDIR / relative).mkdir(parents=True)
    shutil.copy2(SOURCE_DIR / "tests/Scenarios/0010-profile-720p-basic.ini", PROFILE_DIR / "basic.ini")
    (CONFIG_ROOT / "user.ini").write_text(
        "[General]\nFirstRun=true\nLanguage=en-US\nConfirmOnExit=false\n\n"
        "[Basic]\nProfile=obs-backgroundremoval-dev-720p\nProfileDir=obs-backgroundremoval-dev-720p\n",
        encoding="utf-8",
    )
    (CONFIG_ROOT / "global.ini").write_text(
        "[General]\nMacOSPermissionsDialogLastShown=1\n", encoding="utf-8"
    )


def main() -> None:
    prepare_workspace()
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(MacOSAboutDialogOnStartupTest)
    with (ARTIFACTS / "unittest.txt").open("w", encoding="utf-8") as output:
        result = unittest.TextTestRunner(
            stream=output, verbosity=2, failfast=True, resultclass=ScenarioTestResult,
        ).run(suite)
    if result.wasSuccessful():
        print("Native macOS About dialog GUI scenario passed.", flush=True)
    else:
        print(f"macOS scenario artifacts: {ARTIFACTS}", flush=True)
    raise SystemExit(not result.wasSuccessful())


if __name__ == "__main__":
    try:
        main()
    finally:
        if CURRENT_PROCESS is not None:
            stop_obs(CURRENT_PROCESS)
